/** What each capability is, for a palette or a settings screen. */
export const CAPABILITY_INFO: Record<Capability, { title: string; group: string; kind: string; role: string; doc: string }> = {
  'agent.connect': { title: "Connect a protocol agent", group: 'agent', kind: 'command', role: 'operator', doc: "Run an agent's own protocol server and fold its notifications into the session's event stream. Anything the adapter cannot map is reported by name rather than dropped." },
  'agent.interrupt': { title: "Interrupt an agent", group: 'agent', kind: 'command', role: 'operator', doc: "Stop an agent. For an agent with no protocol of its own this is the entire remote control surface." },
  'agent.offers': { title: "What an agent offers", group: 'agent', kind: 'query', role: 'viewer', doc: "Slash commands, tools, models and the pending message queue, as the agent itself reported them. Never a list omt maintains: a completion popup offering a command the agent does not have is worse than none." },
  'agent.threads': { title: "List agent threads", group: 'agent', kind: 'query', role: 'viewer', doc: "Every thread in a session — the main one and each subagent — with what it is doing and any card it raised." },
  'audit.list': { title: "What has been done", group: 'audit', kind: 'query', role: 'admin', doc: "Every call, with who made it and whether it worked. Refusals included: a log of only what succeeded answers the wrong question, because who *tried* to do what is most of what an audit is for." },
  'block.body': { title: "Read a block's output", group: 'block', kind: 'query', role: 'viewer', doc: "The output of one command block, as styled lines. Paged, because a block can hold a whole test run and a phone asking for one over a slow link stalls." },
  'block.rerun': { title: "Re-run a command", group: 'block', kind: 'command', role: 'operator', doc: "Send a block's command to its session again. Refused for a block omt never saw the command of, because the alternative is scraping the screen for something that looks like a prompt." },
  'config.get': { title: "Read configuration", group: 'config', kind: 'query', role: 'viewer', doc: "Resolved settings, each with the layer and file it came from — which is what makes a surprising value traceable." },
  'config.import': { title: "Import settings", group: 'config', kind: 'query', role: 'viewer', doc: "Translate another terminal's settings into omt's, reporting what did not map rather than dropping it. A query: it says what the import would be, and writing it is a separate decision somebody makes." },
  'config.schema': { title: "List every setting", group: 'config', kind: 'query', role: 'viewer', doc: "Every setting with its default, type and description — so a settings screen can be built without knowing the key names in advance. `config.get` reports what is set; this reports what could be." },
  'device.list': { title: "List paired devices", group: 'device', kind: 'query', role: 'operator', doc: "Every device that has been let in, by the name it gave. Pairing mints a credential per device, and a credential nobody can see is one nobody revokes." },
  'device.revoke': { title: "Revoke a device", group: 'device', kind: 'command', role: 'admin', doc: "Stop one device's credential working, leaving every other device alone. This is what makes a lost phone something somebody can act on." },
  'doctor.report': { title: "Write a bug report", group: 'doctor', kind: 'query', role: 'operator', doc: "The diagnosis, the version and what the person was doing, as readable text they can check before sending. Nothing is uploaded: omt has no cloud, and a report somebody cannot read is one they have to trust blindly about their own machine." },
  'doctor.run': { title: "Diagnose this instance", group: 'doctor', kind: 'query', role: 'viewer', doc: "Per-link diagnosis with a remedy on every failure. A check this build cannot perform is reported as not checked rather than as passing: an unrun check reported green is how a diagnosis stops somebody investigating the real problem." },
  'events.subscribe': { title: "Subscribe to events", group: 'events', kind: 'query', role: 'viewer', doc: "Subscribe to the event stream." },
  'fanout.choose': { title: "Choose an arm", group: 'fanout', kind: 'command', role: 'operator', doc: "Record which arm won, naming its branch. Merges nothing and deletes nothing: the losing worktrees are what you would look at to check the choice was right." },
  'fanout.start': { title: "Fan a prompt across agents", group: 'fanout', kind: 'command', role: 'operator', doc: "Create a worktree per agent and record them as one fan-out. Every arm is reported, including any that could not be prepared." },
  'fanout.status': { title: "Fan-out status", group: 'fanout', kind: 'query', role: 'viewer', doc: "Every arm of every fan-out, with its worktree, branch and state." },
  'fs.list': { title: "List files", group: 'fs', kind: 'query', role: 'viewer', doc: "List a directory inside a workspace. Paths are workspace-relative and cannot escape it." },
  'fs.read': { title: "Read a file", group: 'fs', kind: 'query', role: 'viewer', doc: "Read one chunk of a file. Chunked so a large file over a slow link can show progress and resume rather than restarting." },
  'fs.write': { title: "Write a file", group: 'fs', kind: 'command', role: 'operator', doc: "Write one chunk of a file into a workspace. The file appears only once every chunk has arrived." },
  'git.diff': { title: "Git diff", group: 'git', kind: 'query', role: 'viewer', doc: "Which files changed, with line counts. Staged and unstaged are separate answers." },
  'git.hunks': { title: "Diff a file", group: 'git', kind: 'query', role: 'viewer', doc: "The changed lines of one file. `git.diff` reports which files changed; this is what changed in them. Returned as lines rather than rendered, because a terminal, a phone and a browser each want to draw it differently." },
  'git.status': { title: "Git status", group: 'git', kind: 'query', role: 'viewer', doc: "Branch, divergence and working-tree state. Reads only — nothing here commits, checks out or fetches." },
  'help.render': { title: "Show help for a topic", group: 'help', kind: 'query', role: 'viewer', doc: "A model rather than formatted text, so a phone and a terminal can render the same help differently without one of them parsing the other's layout." },
  'help.topics': { title: "Browse help", group: 'help', kind: 'query', role: 'viewer', doc: "Derived from the catalog, not written beside it. Hand-written help is wrong the first time something is renamed and stays wrong, because nothing fails when it drifts." },
  'identity.list': { title: "Who holds what", group: 'identity', kind: 'query', role: 'admin', doc: "Every person this instance knows and the devices each holds. A credential answers whether a token may do something; this answers whose phone it is, which is what makes revoking somebody's access — rather than one token — expressible." },
  'identity.revoke': { title: "Revoke a person's access", group: 'identity', kind: 'command', role: 'admin', doc: "Revoke every device one person holds, in one action. Doing it device by device means somebody who has left keeps whichever one was missed, and there is no moment at which their access is known to be gone." },
  'instance.catalog': { title: "List capabilities", group: 'instance', kind: 'query', role: 'viewer', doc: "Every capability this instance offers." },
  'instance.info': { title: "Instance info", group: 'instance', kind: 'query', role: 'viewer', doc: "Version and protocol of this instance." },
  'instance.metrics': { title: "How the instance is doing", group: 'instance', kind: 'query', role: 'operator', doc: "Clients, sessions, calls and refusals. The health route says the process is up and says nothing else, which is not the same as knowing it is doing anything." },
  'interaction.list': { title: "List open questions", group: 'interaction', kind: 'query', role: 'viewer', doc: "Every interaction waiting for a human, with whether omt can answer it from here and why not when it cannot." },
  'interaction.respond': { title: "Answer a question", group: 'interaction', kind: 'command', role: 'operator', doc: "Answer an open interaction. Exactly once: a second answer is refused with who won, and answerability comes from the deliverable rather than the state." },
  'invite.create': { title: "Invite another device", group: 'invite', kind: 'command', role: 'admin', doc: "A fresh invite, so a second device can be paired from a device already paired. Without it the only invite is the one printed at startup, and adding a phone means restarting the instance everybody else is connected to." },
  'job.create': { title: "Schedule a job", group: 'job', kind: 'command', role: 'operator', doc: "Create a scheduled job, replacing any job of the same name. A missed window is skipped rather than caught up." },
  'job.list': { title: "List scheduled jobs", group: 'job', kind: 'query', role: 'viewer', doc: "Scheduled jobs with when they fire and how many times each has failed in a row." },
  'keys.cheatsheet': { title: "Keyboard reference", group: 'keys', kind: 'query', role: 'viewer', doc: "Every binding and every reserved key, generated from the keymap in force so it cannot go stale." },
  'keys.conflicts': { title: "What a binding would break", group: 'keys', kind: 'query', role: 'viewer', doc: "`Conflicts with something` is not actionable — every chord collides somewhere. This says which program, what the key does there, and how badly it would be missed." },
  'layout.open': { title: "Open a layout", group: 'layout', kind: 'command', role: 'operator', doc: "Start several sessions as a layout, reporting the outcome of every pane rather than only that something failed." },
  'media.attach': { title: "Reference a file to an agent", group: 'media', kind: 'query', role: 'viewer', doc: "Per-adapter, because one format applied to all of them is silently ignored by most — which looks exactly like an agent choosing not to read the file." },
  'media.clipboard': { title: "Copy to local clipboard", group: 'media', kind: 'command', role: 'operator', doc: "OSC 52, wrapped for tmux when TERM says so. omt does not claim the copy succeeded: there is no acknowledgement to base that on." },
  'media.describe': { title: "Identify a blob", group: 'media', kind: 'query', role: 'viewer', doc: "What a blob is, from its bytes rather than from a filename somebody supplied. A name is a claim; the bytes are the evidence, and writing an executable as a `.png` is what trusting the claim allows." },
  'media.get': { title: "Fetch a blob", group: 'media', kind: 'query', role: 'viewer', doc: "By digest, which is the only name a blob has. There is no path to traverse because there is no path." },
  'media.list': { title: "List blobs", group: 'media', kind: 'query', role: 'operator', doc: "A landing zone nobody can see the contents of is one that has quietly become the place things live." },
  'media.paste_tier': { title: "How paste reaches this machine", group: 'media', kind: 'query', role: 'viewer', doc: "A tier is never claimed without a positive handshake. `Probably` means a paste that silently does nothing, and no way for the user to tell whether they mis-copied or omt mis-guessed." },
  'media.put': { title: "Upload a blob", group: 'media', kind: 'command', role: 'operator', doc: "The type is sniffed here and never taken from the sender. A sender that names its own content type decides how the receiver treats it." },
  'migrate.tmux_preview': { title: "Preview a tmux config", group: 'migrate', kind: 'query', role: 'operator', doc: "Every directive comes back classified, including the ones omt cannot map. A migration that silently drops a third of somebody's bindings fails without ever reporting an error." },
  'onboarding.disclosures': { title: "Advanced features", group: 'onboarding', kind: 'query', role: 'viewer', doc: "Every trigger is something the user produced, and every feature is mentioned at most once. Advocacy for a feature somebody has not yet needed spends attention omt will want later." },
  'onboarding.dismiss_hints': { title: "Stop showing tips", group: 'onboarding', kind: 'command', role: 'operator', doc: "Permanent. Somebody who turns tips off and is asked again next week has been told their answer did not count." },
  'onboarding.hint_state': { title: "Show the next tip", group: 'onboarding', kind: 'query', role: 'viewer', doc: "At most one hint is ever offered. Six tips on a first run teach nobody six things; they teach that omt interrupts." },
  'open.click': { title: "Who owns this click", group: 'open', kind: 'query', role: 'viewer', doc: "When the program in the pane has mouse reporting on, every press is its input. A multiplexer that swallows clicks so its own link handler can run has broken vim, and no link feature is worth that." },
  'open.recognize': { title: "Find links and paths", group: 'open', kind: 'query', role: 'viewer', doc: "Paths, URLs and file:line references on a line of output, with their offsets — so a client can make them tappable without inventing its own pattern." },
  'open.remote_discard': { title: "Discard a mirrored file", group: 'open', kind: 'command', role: 'operator', doc: "Unpins the blob so the sweeper can take it. Discarding something already gone is reported, not an error — a retry after a lost acknowledgement must not look like a failure." },
  'open.remote_list': { title: "List mirrored remote files", group: 'open', kind: 'query', role: 'viewer', doc: "A mirror nobody can see is a copy of somebody's file sitting on disk with no way to tell where it came from or to get rid of it." },
  'open.resolve': { title: "Resolve a recognised path", group: 'open', kind: 'query', role: 'operator', doc: "A path resolved against the wrong root opens somebody else's file, so the root that was used is part of the answer and anything escaping every root is refused rather than clamped." },
  'open.rules_list': { title: "List recognition rules", group: 'open', kind: 'query', role: 'viewer', doc: "A recognition system nobody can enumerate is one where `why did that not become a link` has no answer short of reading the source." },
  'open.rules_test': { title: "Test a line against the rules", group: 'open', kind: 'query', role: 'viewer', doc: "Powers the config editor's live preview. Names the rule that fired, because a preview that only says whether something matched cannot help fix one that did not." },
  'pane.close': { title: "Close a pane", group: 'pane', kind: 'command', role: 'operator', doc: "Close a pane. The session it showed keeps running — closing a view of something is not ending it." },
  'pane.focus': { title: "Focus a pane", group: 'pane', kind: 'command', role: 'operator', doc: "Move focus to a pane, which is where typing goes. Focusing a pane that is not there is refused rather than silently ignored." },
  'pane.list': { title: "List panes", group: 'pane', kind: 'query', role: 'viewer', doc: "Panes in a workspace's primary view, which one has focus, and how many fit on a standard terminal." },
  'pane.open': { title: "Open a pane", group: 'pane', kind: 'command', role: 'operator', doc: "Open a pane onto an existing session. Presentation only: no process is started and none is stopped." },
  'plugin.enable': { title: "Enable a plugin", group: 'plugin', kind: 'command', role: 'operator', doc: "Switch a plugin on or off. Idempotent: setting the state it already has is not an error." },
  'plugin.install': { title: "Install a plugin", group: 'plugin', kind: 'command', role: 'operator', doc: "Install a plugin with an explicit grant. What it asks for and what it receives are separate, and what was refused is reported." },
  'plugin.list': { title: "List plugins", group: 'plugin', kind: 'query', role: 'viewer', doc: "Installed plugins with what each was granted, and which of those grants are high-consequence." },
  'plugin.start': { title: "Start a plugin", group: 'plugin', kind: 'command', role: 'operator', doc: "Run a plugin, handing it a socket and a token whose role comes from what it was granted. A plugin reaches omt through the same capability surface as any other client — there is no second API." },
  'presence.list': { title: "Who is connected", group: 'presence', kind: 'query', role: 'viewer', doc: "Every client connected right now. \"Is somebody else looking at this\" is a question people ask before they type, and a terminal that cannot answer it is one where two people interleave keystrokes into one shell." },
  'queue.enqueue': { title: "Queue a message", group: 'queue', kind: 'command', role: 'operator', doc: "Add a message to an agent's queue. Refused where omt only mirrors the queue rather than owning it: a client must be told it cannot write rather than shown a control that silently does nothing." },
  'queue.remove': { title: "Unqueue a message", group: 'queue', kind: 'command', role: 'operator', doc: "Take a message out of an agent's queue. Refused on a mirrored queue for the same reason enqueue is: a removal omt cannot confirm loses the message with no record of what it was." },
  'recall.record': { title: "Record a command", group: 'recall', kind: 'command', role: 'operator', doc: "Add a command to the history that suggestions are drawn from." },
  'recall.suggest': { title: "Suggest a command", group: 'recall', kind: 'query', role: 'viewer', doc: "Commands from history matching a prefix, scored by use in this workspace. Destructive commands are never suggested." },
  'search.session': { title: "Search a session", group: 'search', kind: 'query', role: 'viewer', doc: "Find text across a session's screen and history, with the row and offsets of each hit so a client can scroll to it and highlight exactly that span." },
  'session.acquire': { title: "Take the writer token", group: 'session', kind: 'command', role: 'operator', doc: "Take the writer token for a session, returning the epoch every write is checked against." },
  'session.blocks': { title: "List command blocks", group: 'session', kind: 'query', role: 'viewer', doc: "Commands run in a session with their output ranges and exit codes, from OSC 133. A shell that emits no marks reports none rather than guesses." },
  'session.close': { title: "Close a session", group: 'session', kind: 'command', role: 'operator', doc: "End a session and stop the process on it. Idempotent." },
  'session.create': { title: "Start a session", group: 'session', kind: 'command', role: 'operator', doc: "Start a session in a workspace, running a program on a pty. Deduplicated by intent id, so a reconnect retry does not start a second process." },
  'session.list': { title: "List sessions", group: 'session', kind: 'query', role: 'viewer', doc: "Every session this instance holds, optionally filtered to one workspace." },
  'session.read': { title: "Read a session", group: 'session', kind: 'query', role: 'viewer', doc: "The visible screen as text, optionally with scrollback." },
  'session.release': { title: "Give up the writer token", group: 'session', kind: 'command', role: 'operator', doc: "Give up the writer token. Idempotent: releasing one you do not hold is not an error." },
  'session.resize': { title: "Resize a session", group: 'session', kind: 'command', role: 'operator', doc: "Resize a session. The grid and the kernel are told together, so a program is never handed a size the kernel disagrees with." },
  'session.restart': { title: "Restart a session", group: 'session', kind: 'command', role: 'operator', doc: "Respawn the command behind a session restored from a snapshot, keeping the old output above a separator." },
  'session.scrollback': { title: "Read scrollback", group: 'session', kind: 'query', role: 'viewer', doc: "History as styled lines, by absolute row. Structured rather than raw bytes, so a browser needs no second terminal emulator to show what scrolled past." },
  'session.snapshot': { title: "Snapshot a session", group: 'session', kind: 'query', role: 'viewer', doc: "The visible screen as styled runs, so a remote client renders the same picture as the terminal without emulating one." },
  'session.transcript': { title: "Read an agent transcript", group: 'session', kind: 'query', role: 'viewer', doc: "Messages, reasoning, tool calls and results for an agent session. An agent emits no command marks, so blocks do not apply to it; this is what it is read through instead." },
  'session.write': { title: "Type into a session", group: 'session', kind: 'command', role: 'operator', doc: "Write input to a session, gated on the writer token's epoch." },
  'setup.detect_agents': { title: "Find installed agents", group: 'setup', kind: 'query', role: 'viewer', doc: "Every agent omt can drive, found or not. Listing only what is present hides the difference between an agent omt did not find and one it has never heard of." },
  'shell.integration': { title: "Shell integration status", group: 'shell', kind: 'query', role: 'viewer', doc: "Whether the shell emits command marks, judged by what has been seen rather than by a setting, with the line that enables them. omt prints it and never edits a shell's configuration itself." },
  'ssh.plan': { title: "Preview an omt ssh session", group: 'ssh', kind: 'query', role: 'operator', doc: "An argument vector, never a shell string: a hostname from a config file with a quote in it would otherwise become remote execution." },
  'state.restore': { title: "Restore instance state", group: 'state', kind: 'command', role: 'operator', doc: "Reopen the workspaces from a snapshot, reporting any whose directory is gone rather than dropping them silently." },
  'state.save': { title: "Save instance state", group: 'state', kind: 'command', role: 'operator', doc: "Write the open workspaces to a snapshot a later run can restore. Written atomically: a crash mid-write leaves the previous snapshot, never half of a new one." },
  'term.profile': { title: "Check this terminal", group: 'term', kind: 'query', role: 'viewer', doc: "A wrong TERM does not fail; it draws a subtly wrong screen that people blame on omt for weeks. This says what is advertised, what was observed, and where they disagree." },
  'theme.get': { title: "Read the theme", group: 'theme', kind: 'query', role: 'viewer', doc: "The colours in force, so a remote client renders a session in the user's own theme rather than in its own defaults." },
  'uninstall.apply': { title: "Uninstall omt", group: 'uninstall', kind: 'command', role: 'admin', doc: "Refuses unless it is given the hash of a plan that still matches the disk. A confirmation against a plan that has since changed is a confirmation of something the user never saw." },
  'uninstall.plan': { title: "Preview an uninstall", group: 'uninstall', kind: 'query', role: 'admin', doc: "Driven by the setup manifest. Anything absent from it is never touched — an uninstall that reasons about what it probably wrote eventually removes somebody else's configuration." },
  'usage.report': { title: "Usage and quota", group: 'usage', kind: 'query', role: 'viewer', doc: "Tokens spent per session and in total, with whatever the agent said about its rate limit. Cost appears only when the agent stated one — omt never computes it from a price table of its own." },
  'voice.append': { title: "Add dictated text", group: 'voice', kind: 'command', role: 'operator', doc: "Append a transcript chunk to a session's dictation buffer. Partial chunks are replaced by later ones; only the settled part is offered for sending." },
  'voice.clear': { title: "Clear dictation", group: 'voice', kind: 'command', role: 'operator', doc: "Discard a session's dictation buffer. Idempotent." },
  'voice.providers': { title: "List speech engines", group: 'voice', kind: 'query', role: 'viewer', doc: "Speech-to-text engines this instance can use, and whether each has a key. Presence only — a capability that returned a key would put it in the first log somebody captured." },
  'workspace.list': { title: "List workspaces", group: 'workspace', kind: 'query', role: 'viewer', doc: "Every workspace this instance has open, with its session count." },
  'workspace.open': { title: "Open a workspace", group: 'workspace', kind: 'command', role: 'operator', doc: "Open a workspace at a canonical path. Idempotent: the id is derived from the path." },
  'worktree.add': { title: "Add a worktree", group: 'worktree', kind: 'command', role: 'operator', doc: "Create a git worktree, which becomes a workspace by the id its path derives. Additive: it touches nothing that already exists, and a path already in use is refused rather than overwritten." },
  'worktree.list': { title: "List worktrees", group: 'worktree', kind: 'query', role: 'viewer', doc: "Every worktree of a workspace's repository, with the workspace id each would open as. Read from git rather than from omt's own records, so it cannot disagree with reality." },
  'worktree.remove': { title: "Remove a worktree", group: 'worktree', kind: 'command', role: 'operator', doc: "Remove a worktree. Refused when it has uncommitted changes unless force is given — an agent's output is usually why the worktree was wanted, and deleting it on a tap is unrecoverable." },
}
